            // swap and future
            //
            //     {
            //         "returnCode": 0,
            //         "msgInfo": "success",
            //         "error": null,
            //         "result": {
            //             "page": 1,
            //             "ps": 10,
            //             "total": 2,
            //             "items": [
            //                 {
