            //                     "time": 1679175285162,
            //                     "updatedTime": 1679175488492
            //                 },
            //             ]
            //         }
            //     }
            //
            // spot and margin: fetchOpenOrders
            //
            //     {
            //         "rc": 0,
            //         "mc": "SUCCESS",
            //         "ma": [],
            //         "result": [
            //             {
            //                 "symbol": "eth_usdt",
            //                 "orderId": "208249323222264320",
            //                 "clientOrderId": null,
            //                 "baseCurrency": "eth",
