            //                 "type": "LIMIT",
            //                 "timeInForce": "GTC",
            //                 "price": "1300.00",
            //                 "origQty": "0.0032",
            //                 "origQuoteQty": "4.16",
            //                 "executedQty": "0.0000",
            //                 "leavingQty": "0.0032",
            //                 "tradeBase": "0.0000",
            //                 "tradeQuote": "0.00",
            //                 "avgPrice": null,
            //                 "fee": null,
            //                 "feeCurrency": null,
            //                 "closed": false,
            //                 "state": "NEW",
            //                 "time": 1679352507741,
            //                 "updatedTime": 1679352507869
            //             },
            //         ]
            //     }
            //
            // swap and future
            //
            //     {
            //         "returnCode": 0,
            //         "msgInfo": "success",
            //         "error": null,
            //         "result": {
            //             "page": 1,
            //             "ps": 10,
            //             "total": 25,
            //             "items": [
            //                 {
            //                     "orderId": "207519546930995456",
            //                     "clientOrderId": null,
            //                     "symbol": "btc_usdt",
            //                     "orderType": "LIMIT",
            //                     "orderSide": "BUY",
            //                     "positionSide": "LONG",
            //                     "timeInForce": "GTC",
            //                     "closePosition": false,
            //                     "price": "20000",
            //                     "origQty": "100",
            //                     "avgPrice": "0",
            //                     "executedQty": "0",
            //                     "marginFrozen": "4.12",
            //                     "remark": null,
            //                     "triggerProfitPrice": null,
            //                     "triggerStopPrice": null,
            //                     "sourceId": null,
            //                     "sourceType": "DEFAULT",
            //                     "forceClose": false,
            //                     "closeProfit": null,
            //                     "state": "CANCELED",
            //                     "createdTime": 1679178515689,
            //                     "updatedTime": 1679180096172
