            //                     "state": "USER_REVOCATION",
            //                     "marketOrderLevel": null,
            //                     "createdTime": 1681271998064,
            //                     "updatedTime": 1681273188674,
            //                     "ordinary": false
            //                 },
            //             ]
            //         }
            //     }
            //
            // stop-loss and take-profit
            //
            //     {
            //         "returnCode": 0,
            //         "msgInfo": "success",
            //         "error": null,
            //         "result": {
            //             "page": 1,
            //             "ps": 3,
            //             "total": 2,
            //             "items": [
            //                 {
            //                     "profitId": "216306213226230400",
            //                     "symbol": "btc_usdt",
            //                     "positionSide": "LONG",
            //                     "origQty": "1",
