            put( "TAKE_OVER", "trade" );
            put( "MERGE", "trade" );
            put( "QIANG_PING_MANAGER", "fee" );
            put( "FUND", "fee" );
            put( "FEE", "fee" );
            put( "ADL", "auto-deleveraging" );
